use std::fs
use std::strings

fn main() {
    let data = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut lines: Vec<string> = strings::split(data, "\n")
    let n: int = lines.len() as int
    if n > 0 && lines[n - 1] == "" {
        lines.pop()
    }
    for line in lines {
        let cs = line.chars().collect::<Vec<char>>()
        let mut fields: Vec<string> = []
        let mut cur = ""
        let mut inq = false
        let m: int = cs.len() as int
        let mut i = 0
        while i < m {
            let c = cs[i]
            if inq {
                if c == '"' {
                    if i + 1 < m && cs[i + 1] == '"' {
                        cur = cur + "\""
                        i += 1
                    } else {
                        inq = false
                    }
                } else {
                    cur = cur + c.to_string()
                }
            } else if c == '"' {
                inq = true
            } else if c == ',' {
                fields.push(cur)
                cur = ""
            } else if c != '\r' {
                cur = cur + c.to_string()
            }
            i += 1
        }
        fields.push(cur)
        let mut out = "${fields.len()}: "
        let mut first = true
        for f in fields {
            if !first { out = out + "|" }
            first = false
            out = out + "[" + f + "]"
        }
        println(out)
    }
}

